// Weekly partner onboarding report (Sunday 9:00 Riyadh — start of the Saudi work week).
const tasks = $input.first().json.tasks || [];
const now = Date.now();
const WEEK = 7 * 24 * 3600 * 1000;
const DAY2 = 2 * 24 * 3600 * 1000;

const rows = tasks
  .filter((t) => t.name.startsWith('Onboard: '))
  .map((t) => {
    const [company, city, type, tier] = t.name.replace('Onboard: ', '').split(' | ');
    return {
      company, city, type,
      tier: (tier || '').replace('Tier ', ''),
      status: (t.status?.status || '').toLowerCase(),
      created: Number(t.date_created),
      updated: Number(t.date_updated),
      url: t.url,
    };
  });

const thisWeek = rows.filter((r) => now - r.created < WEEK);
const count = (arr, key) =>
  Object.entries(arr.reduce((m, r) => ((m[r[key]] = (m[r[key]] || 0) + 1), m), {}))
    .sort((x, y) => y[1] - x[1])
    .map(([k, v]) => `${k}: ${v}`)
    .join(' · ') || '—';

const stuck = rows.filter((r) => r.status === 'waiting on documents' && now - r.updated > DAY2);
const ready = rows.filter((r) => r.status === 'ready for review');

const text = [
  `:bar_chart: *Weekly partner onboarding report*`,
  `*New applications this week:* ${thisWeek.length}`,
  `*By tier:* ${count(thisWeek, 'tier')}`,
  `*By city:* ${count(thisWeek, 'city')}`,
  `*By type:* ${count(thisWeek, 'type')}`,
  ``,
  `*Ready for review (${ready.length}):*`,
  ...(ready.length ? ready.map((r) => `• <${r.url}|${r.company}> (${r.city}, Tier ${r.tier})`) : ['• none']),
  ``,
  `*Stuck on documents for 48h+ (${stuck.length}):*`,
  ...(stuck.length ? stuck.map((r) => `• <${r.url}|${r.company}> (${r.city})`) : ['• none 🎉']),
].join('\n');

return [{ json: { text } }];
